#pragma once
#include <JuceHeader.h>
namespace vocalmotion {
inline const juce::Colour ink{0xff080c19},panelInk{0xff101426},edge{0xff414269},blue{0xff4cd9ff},violet{0xffb178ff},text{0xffebefff};
inline void frame(juce::Graphics&g,juce::Rectangle<float>r,const juce::String&title){g.setGradientFill(juce::ColourGradient(juce::Colour(0xff222039),r.getX(),r.getY(),ink,r.getX(),r.getBottom(),false));g.fillRoundedRectangle(r,10);g.setColour(edge);g.drawRoundedRectangle(r.reduced(.6f),10,1);if(title.isNotEmpty()){g.setColour(text);g.setFont(juce::FontOptions(13.f).withStyle("Bold"));g.drawText(title,r.reduced(13,7).removeFromTop(20),juce::Justification::centredLeft);g.setColour(edge.withAlpha(.45f));g.drawHorizontalLine(int(r.getY()+33),r.getX()+12,r.getRight()-12);}}
class Style:public juce::LookAndFeel_V4{
public:Style(){setColour(juce::Slider::textBoxTextColourId,text);setColour(juce::Slider::textBoxBackgroundColourId,juce::Colours::transparentBlack);setColour(juce::Slider::textBoxOutlineColourId,edge.withAlpha(.6f));setColour(juce::ComboBox::backgroundColourId,ink);setColour(juce::ComboBox::textColourId,text);setColour(juce::ComboBox::outlineColourId,edge);setColour(juce::TextButton::textColourOffId,text);setColour(juce::TextButton::textColourOnId,juce::Colours::white);}
 void drawButtonBackground(juce::Graphics&g,juce::Button&b,const juce::Colour&,bool over,bool down)override{auto r=b.getLocalBounds().toFloat().reduced(1);bool on=b.getToggleState();auto c=on?violet:juce::Colour(0xff24253e);if(on){g.setColour(blue.withAlpha(.1f));g.fillRoundedRectangle(r.expanded(1),7);}g.setGradientFill(juce::ColourGradient(c.brighter(over?.2f:0),r.getX(),r.getY(),on?juce::Colour(0xff352b72):ink,r.getX(),r.getBottom(),false));g.fillRoundedRectangle(r,6);g.setColour((on?blue:edge).withAlpha(down?.9f:.65f));g.drawRoundedRectangle(r,6,1);}
 void drawRotarySlider(juce::Graphics&g,int x,int y,int w,int h,float pos,float start,float end,juce::Slider&)override{auto r=juce::Rectangle<float>(x,y,w,h).reduced(6);float rad=std::max(2.f,std::min(r.getWidth(),r.getHeight())*.43f);auto c=r.getCentre();g.setColour(juce::Colours::black.withAlpha(.8f));g.fillEllipse(c.x-rad-4,c.y-rad+1,rad*2+8,rad*2+8);g.setGradientFill(juce::ColourGradient(juce::Colour(0xff49435e),c.x-rad,c.y-rad,juce::Colour(0xff080b13),c.x+rad,c.y+rad,false));g.fillEllipse(c.x-rad,c.y-rad,rad*2,rad*2);g.setColour(violet.withAlpha(.4f));g.drawEllipse(c.x-rad,c.y-rad,rad*2,rad*2,1);juce::Path p;p.addCentredArc(c.x,c.y,rad+3,rad+3,0,start,start+pos*(end-start),true);g.setColour(violet.withAlpha(.12f));g.strokePath(p,juce::PathStrokeType(9));g.setColour(violet.withAlpha(.65f));g.strokePath(p,juce::PathStrokeType(4));g.setColour(blue.interpolatedWith(violet,.65f));g.strokePath(p,juce::PathStrokeType(2));float a=start+pos*(end-start);g.setColour(juce::Colours::white.withAlpha(.9f));g.drawLine(c.x+std::sin(a)*rad*.35f,c.y-std::cos(a)*rad*.35f,c.x+std::sin(a)*rad*.83f,c.y-std::cos(a)*rad*.83f,1.8f);}
 void drawLinearSlider(juce::Graphics&g,int x,int y,int w,int h,float pos,float,float,juce::Slider::SliderStyle,juce::Slider&)override{float cy=y+h*.5f;g.setColour(edge);g.fillRoundedRectangle(x,cy-4,w,8,4);g.setGradientFill(juce::ColourGradient(violet,float(x),cy,blue,float(x+w),cy,false));g.fillRoundedRectangle(x,cy-3,std::max(1.f,pos-x),6,3);g.setColour(violet.withAlpha(.18f));g.fillEllipse(pos-10,cy-10,20,20);g.setColour(text);g.fillEllipse(pos-5,cy-5,10,10);}
};
}
